mapper.select:
/* BulkHistMapper.selectBulkHistList */
( SELECT B_MSG_KEY, LOGIN_ID, USER_ID, TITLE, MSG, REPLACE( REPLACE( REPLACE( CONVERT(VARCHAR(19), IN_TIME, 120), '-', ''), ':', ''), ' ', '') AS IN_TIME, REPLACE( REPLACE( REPLACE( CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') AS REQ_TIME, CNT, STATUS, SVC_TYPE, B_SEQ, SUCC_CNT, FAIL_CNT FROM T_BROADCAST_MSG WHERE REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') >= #{startTime} AND REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') <= #{endTime}
AND TITLE LIKE CONCAT('%', #{bulkTitle}, '%')
)
ORDER BY
${s.selector}
DESC ASC
ORDER BY B_SEQ DESC
OFFSET #{skip} ROWS FETCH NEXT #{take} ROWS ONLY

/*
	BulkHistMapper.selectBulkHistCount
*/

SELECT COUNT(*) FROM (			
	SELECT 1 AS CNT
	FROM T_BROADCAST_MSG
	WHERE REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') >= #{startTime}
		AND REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') <= #{endTime}

		AND TITLE LIKE CONCAT('%', #{bulkTitle}, '%')

) TOTAL

/* BulkHistMapper.selectBulkHistStatusCount */
SELECT COUNT(CASE WHEN TRAN_STATUS = 1 THEN 1 END) AS CNT_STANBY, COUNT(CASE WHEN TRAN_STATUS IN (2, 3) THEN 1 END) AS CNT_TRAN, COUNT(CASE WHEN TRAN_STATUS = 4 AND TRAN_RSLT = '0' THEN 1 END) AS CNT_SUCC, COUNT(CASE WHEN TRAN_STATUS = 5 THEN 1 END) AS CNT_DUP, COUNT(CASE WHEN TRAN_STATUS = 4 AND TRAN_RSLT <> '0' THEN 1 END) AS CNT_SENDFAIL FROM (
SELECT TRAN_STATUS, TRAN_RSLT, B_MSG_KEY FROM ${tableName} WHERE B_MSG_KEY = #{bulkMsgKey}
) T_BROADCAST

/* BulkHistMapper.selectTranPhoneList */
SELECT TRAN_PHONE FROM (
SELECT TRAN_PHONE FROM ${tableName} WHERE ( B_MSG_KEY = #{bulkMsgKey} AND TRAN_STATUS = 5 ) OR ( B_MSG_KEY = #{bulkMsgKey} AND TRAN_STATUS = 4 AND TRAN_RSLT <> '0' )
) A
SELECT TRAN_PHONE FROM ${svcType} WHERE ( B_MSG_KEY = #{bulkMsgKey} AND TRAN_STATUS = 5 ) OR ( B_MSG_KEY = #{bulkMsgKey} AND TRAN_STATUS = 4 AND TRAN_RSLT <> '0' )
